import{_ as a,a as l}from"./chunks/866a98e465daac51aebf.DapEBorF.js";import{_ as r,C as i,o,c as n,j as e,a as s,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"通才的崛起（如何在多重兴趣中茁壮成长）","description":"","frontmatter":{"title":"通才的崛起（如何在多重兴趣中茁壮成长）","originalTitle":"The Rise Of The Generalist (How To Thrive With Multiple Interests)","date":"2024-05-11","originalUrl":"https://thedankoe.com/letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests/","minutes":16,"sourceHash":"0b47aec14cfbc22ae5759bfacfa7857dcb77b43a0ef6a1f623593517fc810a6d","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests/"}]]},"headers":[],"relativePath":"letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests.md","filePath":"letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests.md"}'),u={name:"letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests.md"};function m(d,p,f,g,b,_){const t=i("ArticleMeta");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"通才的崛起-如何在多重兴趣中茁壮成长",tabindex:"-1"},[s("通才的崛起（如何在多重兴趣中茁壮成长） "),e("a",{class:"header-anchor",href:"#通才的崛起-如何在多重兴趣中茁壮成长","aria-label":'Permalink to "通才的崛起（如何在多重兴趣中茁壮成长）"'},"​")],-1)),h(t),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/KTgakWW0Rzw?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我们正处于第二次文艺复兴之中。</p><p>但只有极少数人能看清正在发生什么。</p><p>真正利用它的人更是少之又少。</p><p>你能看清吗？</p><ul><li>创作者经济正以指数级的速度增长。</li><li>人们不再相信传统工作或学校教育能保障他们的未来。</li><li>人们转向创作者，向他们学习在快速变化的数字环境中茁壮成长所需的技能。</li><li>人工智能、自动化和软件让那些想以做自己喜欢的事为生的人更容易做生意。</li><li>人们工作得更少，赚得更多，并利用技术让自己摆脱旧社会的束缚。</li><li>人们渴望在网上与有真性情的人建立人际连接，而不是那些只谈论单一专业兴趣、被美化了的搜索引擎。</li></ul><p>这些都与一个事实有关：技术已经改变了我们的工作方式、工作机会，以及什么才算是有价值的工作。</p><p>如果你想以做自己喜欢的事为生，你生逢其时。</p><p>互联网已经将财富创造去中心化，下放给了那些重视自我教育、个人责任，并渴望通过做好工作来成就人生的人。</p><p>有几个问题促成了这一切。</p><p><strong>1) 专才与其他专才竞争。</strong></p><p>专才是指试图用单一兴趣或技能来实现目标的人。</p><p>就像专注于健身的健美运动员。</p><p>或者在电子游戏中只玩一个定位/职业/角色。</p><p>或者在工作中执行一连串机械的任务。</p><p>成为专才在工业时代是有道理的，但在信息时代就行不通了。</p><p>当健美运动员受伤时，他们要么感到厌倦并停止进步，要么只能从头开始。</p><p>当你在电子游戏中被克制，或者已经有人选了你的角色时，你就会处于巨大的劣势。</p><p>当你的工作由日复一日的重复事务组成时，你不仅成了被取代的首选，生活也失去了滋味，因为没有了能给生活带来意义的挑战或新奇目标……你的时间干瘪了，因为你满脑子想的都是整天工作，每晚累得半死，付清账单，祈祷家人别离开你，诸如此类。</p><p>另一方面，通才则是多元且有趣的。</p><p>大多数人认为，为了获得成功，他们必须在某一件事上做到极其出色。</p><p>社交媒体扭曲了我们对价值的认知。</p><p>你不需要雕刻般的六块腹肌和美黑喷雾来给人留下深刻印象并吸引注意力。</p><p>大多数人会觉得，有一点点肌肉，能做几个引体向上，并且在健身之外还有自己的生活，这就已经令人刮目相看了。</p><p>加上写作的爱好和一些心理学知识，你就能从互联网上的各色人等那里开启一个充满机遇的世界（这是你过去根本无法接触到的）。</p><p>在第二次文艺复兴中，你不需要在某一件事上出类拔萃，你需要在很多事情上达到平均水平。</p><p><strong>2) 互联网偏爱通才。</strong></p><p>当我刚开始做生意时，我被“专注细分领域（niche）”的建议轰炸了。</p><p>人们常说，财富就藏在细分领域里。</p><p>而且不仅是细分一点点，还要<em>深入细分</em>，直到你所学的技能只能帮助到一小撮人。</p><p>这听起来很有道理，但在我眼里，这是过时的建议。</p><p>社交媒体处于注意力的最前沿。</p><p>像付费广告和冷邮件这些东西——你知道的，那些绝对没人喜欢做的事——要求你在信息传达上非常具体，这样你才能找到、定位并把你的工作展现给特定的人。如果你不明白这一点，去上我免费的<a href="https://theone-personbusiness.com/" target="_blank" rel="noreferrer">一人企业基础课程</a>。</p><p>随着营销越来越向社交媒体上的自然流量内容倾斜，情况就不一样了。</p><p>有了内容，你的作品就会暴露在多样化的受众面前，因为社交媒体就是这样运作的。</p><ul><li>算法</li><li>转发和分享</li><li>来自路人的评论</li></ul><p>它们都会把你推向无法预测的受众。</p><p>而且，人们上社交媒体不是为了学习或购买（至少在他们登录社交媒体直到遇到对他们生活有益的东西之前是这样）。他们是为了娱乐。所以，你需要相应地调整你的策略。</p><p>如果你的信息过于局限在某个细分领域，人们就会直接滑过去。</p><p>相反，你必须吸引一群有着广泛兴趣的多元化受众，然后<em>说服</em>他们相信你想要变现的那项技能的重要性。</p><p>如果你谈论的总是你卖的东西，人们很快就会察觉。</p><p>我宁愿拥有一个10万粉丝的多元化受众群，也不要一个1万粉丝的细分领域受众群，因为我懂得如何教育受众。</p><p>我很快就会教你如何做到这一点。</p><p><strong>3) 体力劳动比以往任何时候都更容易被取代。</strong></p><p>社会已经给你布下了失败的陷阱。</p><p>我们正处于一场信念的精神战争之中。</p><p>老一辈人不容许自己的身份认同受到不断变化的外部环境的挑战。他们的思想仍停留在那个时代：上学、找工作、一直工作到死，并有可能换来一个体面的退休生活，那才是明智之举。</p><p>这不是他们的错……这只是人类的本性。信仰体系在集体规模上的进化是需要时间的。</p><p>问题在于，人们会拼命阻挠你去改变。尽管他们嘴上说这么做是出于爱你，但现实是，当你过得比他们好时，他们的身份认同就受到了威胁。</p><p>成为“第二次文艺复兴人”的道路需要精神力量和坚韧不拔的毅力。</p><p>你必须对自己的信念充满确信：你的潜力绝不仅限于找一份在5到10年内就会被机器人取代的工作。</p><p>既然你可以去任何新闻或报道网站亲眼看看，我也就不需要告诉你，大多数学校教育和工作选择都已过时了。</p><h2 id="为什么通才在创作者经济中能茁壮成长" tabindex="-1">为什么通才在创作者经济中能茁壮成长 <a class="header-anchor" href="#为什么通才在创作者经济中能茁壮成长" aria-label="Permalink to &quot;为什么通才在创作者经济中能茁壮成长&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>只有奴隶才会被指望一辈子只干一件事。</p><p>这正是我们当前的教育和就业体系所反映的现实。</p><p>薪资奴役（wage slavery）是非常真实的现象。</p><p>另一方面，“自由人”被定义为根据自己的兴趣行动，并在其一生中做很多事情的人。</p><p>如果你不为自己设定目标，就会被强加一个目标，而社会非常擅长给那些缺乏独立思考能力的人派发目标。</p><p>通才是出于实现人生目标的兴趣，而去学习所有相关知识和技能的人。</p><p>这对我是自然而然的事，我确信对于读到这里的许多人来说也是如此。</p><p>我很感激有一群能对我的失败产生共鸣的受众。</p><p>所以，对于那些仍在战壕里苦苦挣扎的人，我想提供一些清晰的思路。</p><p>我在代发货（dropshipping）、电子商务、搜索引擎优化（SEO）、数字艺术等方面都失败过。</p><p>但在追求商业目标的过程中，我叠加出了一套无可替代的技能。</p><p>一两项技能并没有给我带来多大的成果。</p><p>但五项……六项……七项技能让我能够发现并抓住有利可图的机会，因为我有了更多的工具去解决更多的问题。</p><p>代发货教会了我品牌建设，让我能够在大品牌低配送时间的夹击中脱颖而出。</p><p>电子商务教会了我广告和产品设计，让我更能吸引眼球。</p><p>数字艺术教会了我平面设计，以及在社交媒体上积累受众的微妙技巧。</p><p><em>请注意，我并没有通过无休止地看教程来学习这些技能。我设定的目标是为自己工作，启动了一个项目，并在边学边做的过程中练习这些技能。</em></p><p>所有这些“失败”都是我今天能做成我现在所做之事的根基。</p><p>这个故事之所以重要，有两个原因。</p><h3 id="_1-失败叠加让你变得无可替代" tabindex="-1">1) 失败叠加让你变得无可替代 <a class="header-anchor" href="#_1-失败叠加让你变得无可替代" aria-label="Permalink to &quot;1) 失败叠加让你变得无可替代&quot;">​</a></h3><p>大多数人都知道什么是“技能叠加”。</p><p>它就像一个多样化的股票投资组合。</p><p>你不是把所有的钱都投在一只股票上——就像个专才那样——为自己埋下灾难的伏笔，而是投资于各种不同的股票，以增加成功的机会。</p><p>即使有一只股票下跌，另外几只可能在涨，你依然能获利。</p><p>如果你有天赋打进NBA或是斩获白金唱片，你现在早就该知道了。</p><p>从统计学上讲，在某一件特定的事情上做到绝对第一几乎是不可能的。</p><p>然而，在你觉得有趣的几个领域进入前25%……那其实相当容易。</p><p>为了让这个概念更容易理解，我们把“技能叠加”重新定义为“失败叠加”。</p><p>获取技能的心态会让你以为自己只需要成天埋头苦学。</p><p>而获取失败的前提是，你在积极地朝着目标努力，并获得了真刀真枪的经验。</p><ul><li><strong>确定一个人生目标</strong> —— 比如辞掉工作、找个伴侣，或者健身。</li><li><strong>从你已知的开始</strong> —— 你只有在遇到路障时，才知道该学什么，所以赶紧去碰壁吧。</li><li><strong>追随你的好奇心</strong> —— 让你的经验引导你走向新的路径去尝试。</li></ul><p>所有这些最终都会产生交集。</p><p>从健身开始，你可以接触到值得尝试的饮食模式、有待测试的训练计划，以及需要贯彻的生活方式转变。</p><p>一旦你进入了前25%（这在健身领域并不算难），你就可以探索新的路线了。</p><p>也许你想在健身行业开启一番事业，所以你开始在网上写作并建立受众群体。</p><p>同样的，一旦你跻身前25%（这依然不算难），你就可以通过涉猎其他领域来扩大你的战果。</p><p>你可以学习哲学来增加你写作的深度，学习设计来提升你的品牌，或者作为创作者去学习任何你想学的东西——这就是为什么通才能够茁壮成长。</p><h3 id="_2-最赚钱的细分领域就是你自己" tabindex="-1">2) 最赚钱的细分领域就是你自己 <a class="header-anchor" href="#_2-最赚钱的细分领域就是你自己" aria-label="Permalink to &quot;2) 最赚钱的细分领域就是你自己&quot;">​</a></h3><p>创作者经济——不要跟网红经济（influencer economy）混为一谈——其特点是个人追求自己的兴趣并记录下自己的知识。</p><p>没人愿意关注一个整天只谈论同一件事、被美化了的搜索引擎。</p><p>很多创作者告诉我，他们不敢涉足新的兴趣领域，因为他们不明白那将如何运作。</p><p>你只需要看看你关注的所有人。他们真的只谈论<em>一</em>件事吗？真的吗？</p><p>还是说，他们把自己的观点、信念、知识和生活经验的片段，包装成了极具影响力的内容？</p><p>“可是Dan，那我该卖什么呢？”</p><p>这就是事情变得棘手的地方。</p><h2 id="通才如何谋生" tabindex="-1">通才如何谋生 <a class="header-anchor" href="#通才如何谋生" aria-label="Permalink to &quot;通才如何谋生&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>作为通才谋生的第一步，是选择一条不会把你框死在某一特定技能或兴趣中的职业道路。</p><p>换句话说，你需要成为一名创业者（entrepreneur）。</p><p>但光靠这还不够。</p><p>你很容易就会被困在某个特定的细分领域中，做着你觉得不再有意义的工作。</p><p>正如前面提到的，你正处在第二次文艺复兴之中。</p><p>社交媒体就是新的城市广场。</p><p>创作者就是新的“文艺复兴人”。</p><p>创作者构成了去中心化的教育系统。</p><p>创作者就是新经济。</p><p>别再把“创作者”看作是什么新兴的互联网工作了。把这当成生活的一部分。你一天的大部分时间本来就已经花在手机上了。事到如今，如果还要表现得好像社交媒体没有根植于人类社会，那简直是愚蠢至极。成为一名“创作者”只不过是在数字世界里表达你的价值，而不是在场边做它的奴隶。</p><p>你为了获取知识和娱乐去关注创作者，可能是因为他们展示了与你从小听到的截然不同的信念和机会。</p><p>思想正在塑造社会，而这一切正在你眼前发生。</p><p>创作者们通过追求自己的兴趣，并教授他们所知道的东西来赚取独立的收入。</p><p>他们解决自己生活中的问题，并出售解决方案。</p><p>有些人出售时尚的防蓝光眼镜来帮助睡眠。有些人出售商业建议，因为大学教授可能自己根本没有经营过企业（除非他们完全是出于热情在教学，并且早就腰缠万贯），所以创作者是少数有资格教授商业知识的人之一。还有些人出售生产力系统、心理学实践和冥想方法。</p><p>如果你没看到这些，那可能是时候取关所有人，开始在互联网上寻找那些正在创造你希望在世界上看到的社会的角落了。你的注意力总要有去处，倒不如用来为你所信仰的事物（以及你想成为的人）添砖加瓦。</p><p>让我们从这里开始。你该如何开始谋生？</p><h3 id="建立广泛受众" tabindex="-1">建立广泛受众 <a class="header-anchor" href="#建立广泛受众" aria-label="Permalink to &quot;建立广泛受众&quot;">​</a></h3><p>我不赞成建立“细分领域”或特定的受众群体。</p><p>我赞成的是，用任何能提供帮助的技能、兴趣和想法，去帮助你的受众实现一个大目标。</p><p>当人们告诉你针对特定话题建立细分领域受众时，他们通常没有意识到，他们自己根本就不是这么做的。</p><p>他们嘴上这么说，然后就继续分享各种随机的心态建议，讨论他们的信念，发发生活日常，并探讨他们的其他兴趣。</p><p>在做任何事之前，为什么要建立受众群体？</p><p>因为如果你想获得独立收入，你需要注意力和人。</p><p>你再也不能指望你的老板通过营销部门来吸引注意力、销售他们的产品了。你必须全靠自己。</p><p>对初学者来说，建立受众是实现这一点最容易上手的方式。你只需要网络连接，一些想法，以及在键盘上打字的能力。我在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2-Hour Writer</a> 中教过这些。</p><p>简单来说：</p><ul><li><strong>选择一个大目标</strong> —— 是财务自由？是健美的身体？是自我实现？作为一个价值创作者（专注于价值和教育，而非娱乐和颜值），你的目的是帮助人们改善思想、身体、业务和人际关系。</li><li><strong>列出技能、兴趣和信念</strong> —— 人们需要知道什么才能实现这个目标？这些元素的组合构成了你的独特之处。</li><li><strong>从实现该目标的视角来框定你写的所有内容</strong> —— 如果因为某种原因你想谈论编篮子，那就谈吧，但要讲讲这作为一个有趣的爱好如何有益于你的生活，如何帮助你提升创造力和头脑清晰度。</li></ul><p>假设我正在帮助人们实现的目标是财务自由。</p><p>那么我会谈论创造力、心理学、写作和人类潜能，来帮助人们达到那个目标。</p><p>另一个人可以选择完全不同的东西，比如表现/健康、预算和灵性。</p><p>两者都有着每个人都向往的同一个大目标——财务自由——但通往目标的路径却截然不同。</p><p>大多数创作者面临的问题是，他们要么没有一个目标来框定他们的内容，要么选择了一个人们不想要的目标，要么选的目标太小导致只吸引到一小撮受众。</p><p>目标越大，你的潜在受众群就越大，你也能变得越独特。</p><h3 id="制造噪音-寻找信号" tabindex="-1">制造噪音，寻找信号 <a class="header-anchor" href="#制造噪音-寻找信号" aria-label="Permalink to &quot;制造噪音，寻找信号&quot;">​</a></h3><p>大多数创作者迟迟无法开始写作，因为他们不知道写什么。</p><ol><li>直接开始写吧。当你零粉丝的时候，根本没人在看。</li><li>如果你的朋友关注了你，很好。也许终于到了让他们了解真正的你，并有可能加入你的时候了。如果他们不喜欢，也许他们并没有真正关心你，你应该现在就看清这一点，而不是等到以后。</li><li>写下你所有的兴趣。制造大量噪音，让你的受众来决定他们想从你这儿听到更多什么内容。几篇表现不佳的帖子不是世界末日；那是数据。</li></ol><p>当然，发布优质内容只是社交媒体增长的其中一面。如果你想增长，你必须把社交媒体当作一项技能去理解。我在 <a href="/letters/how-to-actually-grow-on-social-media-what-they-dont-tell-you">How To Actually Build An Audience On Social Media</a>（社交媒体实战涨粉避坑指南）中探讨过这项技能。</p><p>下一个问题：我要怎么写？</p><p>首先，基于你的兴趣列出一个内容创意清单。</p><p>其次，专注于“怎么做（how）”和“为什么（why）”。</p><p>第三，把帖子写出来。</p><p>第四，通过你的大目标去过滤它。</p><p>假设我在写心理学相关的文章。</p><p>一些主题包括：</p><ul><li>我该如何管理自己的情绪？列出一系列步骤。</li><li>我为什么要管理自己的情绪？根据经验想出令人信服的理由。</li></ul><p>用一个大目标（如财务自由）将它框定，你就得到了一篇帖子：</p><blockquote><p>如何管理你的情绪：</p><ul><li>察觉负面反应</li><li>在采取行动前按下暂停键</li><li>保持沉默或做出更好的决定</li></ul><p>当你重复这个过程，你就重塑了你的心智，使其不再那么消极。</p><p>你的生活、金钱和人际关系都会顺畅无阻。</p></blockquote><p>只需要稍微提及一下你的大目标，就能让它产生影响力。</p><p>我们为什么要专注于阐述一个想法的“为什么”或重要性？</p><p>因为人们总是抱怨得多，尝试得少。</p><p>“Dan，如果根本没人对我的兴趣感兴趣，我还怎么谈论它们呢？”</p><p>这不是他们的错。是你的错。你的兴趣之所以无趣，是因为你没有把它们变得有趣。</p><p>如果你对它们<em>变得</em>感兴趣，这意味着存在一系列想法和观念，能让它对其他人也变得重要。</p><p>你并非生来就有这种兴趣。你是被一步步设定出这种兴趣的。你被它的重要性所说服，并采纳它来帮助你实现人生目标。</p><p>这确实需要你思考。第一次做多半没那么容易。</p><h3 id="通过数字资产建立权威" tabindex="-1">通过数字资产建立权威 <a class="header-anchor" href="#通过数字资产建立权威" aria-label="Permalink to &quot;通过数字资产建立权威&quot;">​</a></h3><p>到了这个阶段，你已经写了不少帖子了。</p><p>你应该每周复盘它们的表现，看看哪些想法比其他的好。通常哪些表现亮眼会非常明显。</p><p>你可以去寻找文笔更好或互动量更高的内容。</p><p>从那里开始，你要充分利用这些想法：</p><ul><li>将它们转化为较长形式的内容，比如推特贴子串（thread）、轮播图、新闻通讯（newsletter）或视频。</li><li>从多个角度重写这篇帖子，以持续获得更多互动。</li><li>把这个话题融入你的写作常规，让它成为你个人品牌的一部分。</li></ul><p>如果这个话题对你一直效果不错，那就通过创建一个数字资产，来在这个话题上确立你的一席权威。</p><p>创建一个免费产品。在个人资料里置顶一个帖子串或轮播图。把它写下来，作为未来数字产品的一个潜在起点。这就是我在我的新课程 <a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a> 中教授的将你的创意工作变现的方法。该课程将于 6 月 3 日早鸟价上调时正式推出。</p><p>我们为什么要这么做？</p><p>这样你才不会觉得必须一直像复读机一样，把自己局限在某个细分领域里。</p><p>免费产品将包含你所知道的关于该主题的几乎所有内容。</p><p>你不需要在这个话题上没完没了地写内容，你只需直接引导他们去看免费产品，或者让他们阅读你置顶的帖子串。</p><p>这为你继续尝试新想法留出了空间，使你的品牌多样化，并让你成为一个不可替代的通才。</p><p>当你在制造噪音并找到信号时，你将通过不断重组那个想法、创造新的免费产品来吸引人们加入你的邮件列表，从而将该信号巩固为你品牌的一部分。</p><h3 id="建立收入来源组合" tabindex="-1">建立收入来源组合 <a class="header-anchor" href="#建立收入来源组合" aria-label="Permalink to &quot;建立收入来源组合&quot;">​</a></h3><p>作为通才，我们可以向几个人寻找灵感。</p><p>首先，有 Zuby。</p><p>他不仅是个说唱歌手、健身狂热者，还是个政治评论员。</p><p>凭借相当广泛的受众群体，他推广自己的音乐、健身电子书以及公开演讲活动。他没有被局限在某一个特定话题中，这就是他脱颖而出的原因。</p><p>我倾向于把自己当作另一个例子。</p><p>尽管我是从网页设计起步的，但这并没有阻止我谈论情绪管理和自我提升。</p><p>这也没有阻止我打造更多产品，比如实体手帐本和自助类电子书（那本名为《权力之路》的书完全是一坨狗屎（sh*t），但它让我变得更好，最终得以撰写并出版了一本完整的书）。</p><p>随着我的受众增加——这得益于吸引了那些在生活中追求更高成就、胸怀大志的人——我能够从网页设计转型到写作、生产力、品牌建设和营销领域。</p><p>我甚至不会说这些是我的兴趣。老实说，我脑子里有什么想法，我就聊什么。因为如果在我的目标下这些对我而言很重要，那么它们也能<em>变成</em>对那些有共同目标的人同样重要的东西——而这样的人并不在少数。</p><p>简而言之，围绕那些对你效果出众的想法推出产品。</p><p>用课程、训练营、模板、系统、教程来变现，或者任何能帮助人们实现一个小目标、从而让他们离大目标更近几步的东西都可以。</p><p>每 3-6 个月，至少推出一款免费产品和一款付费产品，直到你拥有一个令自己满意的品牌和业务。</p><p>一旦你有了<em>现金流</em>，那你就可以考虑打造需要资本投资并且面向庞大受众群体销售的产品了。我不是在什么富裕家庭长大的。我从未有过任何可投资的资本。我必须创造属于自己的实质性收入来源，才能做像出版自己的书和建立软件初创公司这样的事。</p><p>在一个走向数字化的世界里，这就是作为通才谋生的方式。</p><p>感谢你的阅读，祝你今天剩下的时间愉快。</p><p>– Dan</p><hr><p><a href="/en/letters/the-age-of-the-generalist-how-to-thrive-with-multiple-interests">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',190))])}const T=r(u,[["render",m]]);export{q as __pageData,T as default};
